//! 実行中の調査（`kuda diagnose`）の記録。
//!
//! 調査プロセスは detach されるので、check からは親子関係でたどれない。
//! そこで調査の間だけ、状態ディレクトリに (PID, 起動時刻) を置き、
//! プロセスの監視が kuda 自身の仲間として除外できるようにする。

use crate::known_set;
use crate::paths::Paths;
use crate::probe::ProcessInfo;
use anyhow::{Context, Result};
use std::path::PathBuf;

const PREFIX: &str = "investigating-";

/// 記録を、Drop で消す。異常終了で残っても、`running` が生きていないものとして無視する
pub struct Registration(PathBuf);

impl Drop for Registration {
    fn drop(&mut self) {
        // 消せなくても出来ることがない。残っても害はない（`running` が無視し、次の調査が上書きする）
        let _ = std::fs::remove_file(&self.0);
    }
}

/// 自プロセスを調査プロセスとして記録する。
/// `processes` は今の列挙結果で、自分の起動時刻を引くのに使う。引けなければ記録しない
pub fn register(
    paths: &Paths,
    watch: &str,
    processes: &[ProcessInfo],
) -> Result<Option<Registration>> {
    let Some((pid, started)) = known_set::own_root(processes) else {
        return Ok(None);
    };
    let path = paths.data_dir.join(format!("{PREFIX}{watch}"));
    std::fs::write(&path, format!("{pid} {started}"))
        .with_context(|| format!("failed to write {}", path.display()))?;
    Ok(Some(Registration(path)))
}

/// 生きている調査プロセスの (PID, 起動時刻)。
/// 一致するプロセスがいない記録は無視するだけで消さない。check の列挙の直後に始まった調査の
/// 記録も、列挙結果には一致しないので、消すと生きている調査を巻き込む
pub fn running(paths: &Paths, processes: &[ProcessInfo]) -> Vec<(u32, i64)> {
    let Ok(entries) = std::fs::read_dir(&paths.data_dir) else {
        return Vec::new();
    };
    let mut roots = Vec::new();
    for entry in entries.flatten() {
        if !entry.file_name().to_string_lossy().starts_with(PREFIX) {
            continue;
        }
        let Some(root) = std::fs::read_to_string(entry.path())
            .ok()
            .and_then(|text| parse(&text))
        else {
            // 書き込み途中かもしれないので、読めないものは触らない
            continue;
        };
        if processes
            .iter()
            .any(|p| p.pid == root.0 && p.started == Some(root.1))
        {
            roots.push(root);
        }
    }
    roots
}

fn parse(text: &str) -> Option<(u32, i64)> {
    let (pid, started) = text.trim().split_once(' ')?;
    Some((pid.parse().ok()?, started.parse().ok()?))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn paths(name: &str) -> Paths {
        let dir = std::env::temp_dir().join(format!("kuda-inv-{name}-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        Paths {
            config_dir: dir.clone(),
            data_dir: dir.clone(),
            incidents_dir: dir.clone(),
            logs_dir: dir.clone(),
            reports_dir: dir.clone(),
            lock_dir: dir,
            lock_fallback: false,
        }
    }

    fn me(started: i64) -> ProcessInfo {
        ProcessInfo {
            pid: std::process::id(),
            ppid: None,
            name: "kuda".to_string(),
            path: None,
            user: None,
            started: Some(started),
        }
    }

    #[test]
    fn registration_is_visible_while_alive_and_removed_on_drop() {
        let paths = paths("live");
        let processes = [me(42)];
        let registration = register(&paths, "w", &processes).unwrap().unwrap();
        assert_eq!(running(&paths, &processes), [(std::process::id(), 42)]);
        drop(registration);
        assert!(running(&paths, &processes).is_empty());
        std::fs::remove_dir_all(&paths.data_dir).unwrap();
    }

    #[test]
    fn stale_records_are_ignored_but_kept() {
        let paths = paths("stale");
        let registration = register(&paths, "w", &[me(42)]).unwrap().unwrap();
        // 同じ PID でも起動時刻が違えば、別のプロセスが PID を再利用している
        assert!(running(&paths, &[me(43)]).is_empty());
        // 消さない。列挙の直後に始まった調査の記録かもしれない
        assert!(registration.0.exists());
        assert_eq!(running(&paths, &[me(42)]).len(), 1);
        std::mem::forget(registration);
        std::fs::remove_dir_all(&paths.data_dir).unwrap();
    }

    #[test]
    fn nothing_is_recorded_without_a_start_time() {
        let paths = paths("nostart");
        let mut unknown = me(1);
        unknown.started = None;
        assert!(register(&paths, "w", &[unknown]).unwrap().is_none());
        std::fs::remove_dir_all(&paths.data_dir).unwrap();
    }

    #[test]
    fn unreadable_records_are_left_alone() {
        let paths = paths("garbage");
        let file = paths.data_dir.join(format!("{PREFIX}w"));
        std::fs::write(&file, "12").unwrap();
        assert!(running(&paths, &[me(1)]).is_empty());
        assert!(file.exists());
        std::fs::remove_dir_all(&paths.data_dir).unwrap();
    }
}
//! 調査プロセスを親から切り離して起動する。
//!
//! スケジューラはタスクの終了時に残ったプロセスも止めるので、そのまま子として
//! 起動すると調査が途中で消える。

use anyhow::{Context, Result};
use std::path::Path;
use std::process::{Command, Stdio};

/// 切り離した調査は誰も画面で見ていないので、通知を求める（設定で切っていれば出ない）
fn diagnose_command(program: &Path, watch: &str, incident_dir: &Path) -> Vec<String> {
    vec![
        program.display().to_string(),
        "diagnose".to_string(),
        "--watch".to_string(),
        watch.to_string(),
        "--incident".to_string(),
        incident_dir.display().to_string(),
        "--notify".to_string(),
    ]
}

pub fn spawn_diagnose(watch: &str, incident_dir: &Path) -> Result<()> {
    let program = std::env::current_exe().context("failed to locate the kuda binary")?;
    spawn(watch, &diagnose_command(&program, watch, incident_dir))
}

fn base_command(argv: &[String]) -> Command {
    let mut command = Command::new(&argv[0]);
    command
        .args(&argv[1..])
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null());
    command
}

#[cfg(windows)]
fn spawn(_watch: &str, argv: &[String]) -> Result<()> {
    use std::os::windows::process::CommandExt;

    const CREATE_BREAKAWAY_FROM_JOB: u32 = 0x0100_0000;
    const DETACHED_PROCESS: u32 = 0x0000_0008;
    const CREATE_NO_WINDOW: u32 = 0x0800_0000;
    const ERROR_ACCESS_DENIED: i32 = 5;

    let flags = DETACHED_PROCESS | CREATE_NO_WINDOW;
    let result = base_command(argv)
        .creation_flags(flags | CREATE_BREAKAWAY_FROM_JOB)
        .spawn();
    match result {
        Ok(_) => Ok(()),
        // ジョブが離脱を許可していないと失敗する。切り離せなくても調査は試みる
        Err(error) if error.raw_os_error() == Some(ERROR_ACCESS_DENIED) => {
            log::warn!("job does not allow breakaway; diagnose may end with the task");
            base_command(argv)
                .creation_flags(flags)
                .spawn()
                .map(drop)
                .context("failed to start diagnose")
        }
        Err(error) => Err(error).context("failed to start diagnose"),
    }
}

#[cfg(unix)]
fn spawn(watch: &str, argv: &[String]) -> Result<()> {
    use crate::exec;
    use std::os::unix::process::CommandExt;
    use std::time::Duration;

    // ユーザーの systemd が動いていれば別ユニットにする。cgroup ごと止められずに済み、
    // 同名ユニットが動いていれば起動に失敗するので多重起動防止にもなる
    if std::env::var_os("XDG_RUNTIME_DIR").is_some()
        && let Some(systemd_run) = exec::find_program("systemd-run")
    {
        let mut command = exec::command(systemd_run);
        command.args(systemd_run_args(watch, |key| std::env::var(key).ok()));
        command.args(argv);
        match exec::run(command, None, Duration::from_secs(10)) {
            Ok(output) if output.success() => return Ok(()),
            Ok(output) if output.stderr.contains("already") => {
                log::info!("diagnose for {watch} is already running");
                return Ok(());
            }
            Ok(output) => log::warn!("systemd-run failed: {}", output.stderr.trim()),
            Err(error) => log::warn!("systemd-run failed: {error:#}"),
        }
    }

    // cron など systemd の外から起動された場合は、セッションから切り離すだけにする
    base_command(argv)
        .process_group(0)
        .spawn()
        .map(drop)
        .context("failed to start diagnose")
}

/// 別ユニットはサービスマネージャの環境で動くので、解決に使う変数を引き継ぐ
#[cfg(any(unix, test))]
fn systemd_run_args(watch: &str, env: impl Fn(&str) -> Option<String>) -> Vec<String> {
    let mut args = vec![
        "--user".to_string(),
        "--collect".to_string(),
        "--quiet".to_string(),
        format!("--unit=kuda-diagnose-{watch}"),
    ];
    for key in [
        "PATH",
        "KUDA_HOME",
        "XDG_CONFIG_HOME",
        "XDG_STATE_HOME",
        "XDG_DATA_HOME",
    ] {
        if let Some(value) = env(key) {
            args.push(format!("--setenv={key}={value}"));
        }
    }
    args
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn builds_diagnose_arguments() {
        let argv = diagnose_command(Path::new("kuda"), "w", Path::new("incident"));
        assert_eq!(
            argv,
            [
                "kuda",
                "diagnose",
                "--watch",
                "w",
                "--incident",
                "incident",
                "--notify"
            ]
        );
    }

    #[test]
    fn systemd_unit_is_named_after_the_watch_and_keeps_env() {
        let args = systemd_run_args("w", |key| (key == "PATH").then(|| "/bin".to_string()));
        assert!(args.contains(&"--unit=kuda-diagnose-w".to_string()));
        assert!(args.contains(&"--setenv=PATH=/bin".to_string()));
        assert!(!args.iter().any(|arg| arg.contains("KUDA_HOME")));
    }
}
//! OS 別のディレクトリ解決。Linux は XDG Base Directory Specification に従う。

use crate::os::Os;
use anyhow::{Context, Result, anyhow};
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, PartialEq)]
pub struct Paths {
    pub config_dir: PathBuf,
    pub data_dir: PathBuf,
    pub incidents_dir: PathBuf,
    pub logs_dir: PathBuf,
    pub reports_dir: PathBuf,
    pub lock_dir: PathBuf,
    /// XDG_RUNTIME_DIR が無くロックを state 側へ退避したとき true
    pub lock_fallback: bool,
}

impl Paths {
    pub fn config_file(&self) -> PathBuf {
        self.config_dir.join("config.toml")
    }

    pub fn db_file(&self) -> PathBuf {
        self.data_dir.join("kuda.db")
    }

    pub fn lock_file(&self) -> PathBuf {
        self.lock_dir.join("kuda.lock")
    }

    pub fn from_env() -> Result<Self> {
        Self::resolve(Os::current(), |key| std::env::var(key).ok())
    }

    fn resolve(os: Os, env: impl Fn(&str) -> Option<String>) -> Result<Self> {
        let var = |key: &str| env(key).filter(|v| !v.is_empty());

        if let Some(home) = var("KUDA_HOME") {
            let root =
                std::path::absolute(&home).with_context(|| format!("invalid KUDA_HOME: {home}"))?;
            return Ok(Self::single_root(root));
        }
        if os == Os::Windows {
            // 設定はユーザーに付いて回るもの、それ以外はこの PC に固有のもの
            let roaming = var("APPDATA").ok_or_else(|| anyhow!("APPDATA is not set"))?;
            let local = var("LOCALAPPDATA").ok_or_else(|| anyhow!("LOCALAPPDATA is not set"))?;
            return Ok(Self {
                config_dir: PathBuf::from(roaming).join("kuda"),
                ..Self::single_root(PathBuf::from(local).join("kuda"))
            });
        }

        let home = var("HOME").ok_or_else(|| anyhow!("HOME is not set"))?;
        // 仕様どおり、相対パスの値は無効として既定値へ戻す
        let xdg = |key: &str, default: &str| {
            var(key)
                .map(PathBuf::from)
                .filter(|p| p.is_absolute())
                .unwrap_or_else(|| Path::new(&home).join(default))
                .join("kuda")
        };
        let state = xdg("XDG_STATE_HOME", ".local/state");
        let runtime = var("XDG_RUNTIME_DIR")
            .map(PathBuf::from)
            .filter(|p| p.is_absolute());

        Ok(Self {
            config_dir: xdg("XDG_CONFIG_HOME", ".config"),
            incidents_dir: state.join("incidents"),
            logs_dir: state.join("logs"),
            reports_dir: xdg("XDG_DATA_HOME", ".local/share").join("reports"),
            lock_fallback: runtime.is_none(),
            lock_dir: runtime.map_or_else(|| state.join("run"), |dir| dir.join("kuda")),
            data_dir: state,
        })
    }

    fn single_root(root: PathBuf) -> Self {
        Self {
            data_dir: root.join("data"),
            lock_dir: root.join("data"),
            incidents_dir: root.join("incidents"),
            logs_dir: root.join("logs"),
            reports_dir: root.join("reports"),
            config_dir: root,
            lock_fallback: false,
        }
    }

    /// 書き込み先のディレクトリを用意する
    pub fn ensure_dirs(&self) -> Result<()> {
        for dir in [
            &self.data_dir,
            &self.incidents_dir,
            &self.logs_dir,
            &self.reports_dir,
            &self.lock_dir,
        ] {
            create_private_dir(dir)?;
        }
        Ok(())
    }
}

/// 無ければ 0700 で作成する。既にあるディレクトリのパーミッションは変えない
pub fn create_private_dir(dir: &Path) -> Result<()> {
    let mut builder = std::fs::DirBuilder::new();
    builder.recursive(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::DirBuilderExt;
        builder.mode(0o700);
    }
    builder
        .create(dir)
        .with_context(|| format!("failed to create {}", dir.display()))
}

