    /// 保持期間内の probe 回数
    pub fn sample_count(&self, watch: &str) -> Result<u64> {
        let count: i64 = self.conn.query_row(
            "SELECT COUNT(DISTINCT ts) FROM metrics WHERE watch = ?1",
            params![watch],
            |row| row.get(0),
        )?;
        Ok(count as u64)
    }

